"use client";
// @motomation-component
// id: hold-to-commit
// name: Hold to Commit
// family: micro
// tier: 2
// deps: react
// what: An important action fills while you press and hold, and only confirms when the fill completes; letting go early drains it back.
// use-when: Irreversible or weighty actions: delete, publish, donate, sign.
// avoid-when: Everyday actions; anything time-critical; as the only way to confirm (keyboard users get Enter-to-hold too).
// reduced-motion: The fill still shows progress (it's information) but with a linear, unanimated drain.
// touch: Press and hold works with touch; long-press callouts are suppressed.
// a11y: A real button; Space or Enter held works like a press; the label says "Hold to …"; aria-live announces completion. A click that was not a hold (screen readers, voice control and switch access synthesize these) arms a confirmation instead: the label becomes "Press again to confirm", it is announced, and a second activation within 6 s commits; double-clicks don't count. Pending frames are cancelled on unmount, and a hold stops if the window loses focus or the tab is hidden.
import { useEffect, useRef, useState, type CSSProperties } from "react";
import { useReducedMotion } from "../_lib/motion";

type Props = { label: string; doneLabel?: string; confirmLabel?: string; holdMs?: number; onCommit: () => void; className?: string; style?: CSSProperties };

const ARM_MS = 6000; // how long an armed confirmation stays open
const GAP_MS = 400; // a confirming click must come at least this long after the arming one (not a double-click)
const TAP_MS = 250; // a press shorter than this is a tap, not a hold

export function HoldToCommit({ label, doneLabel = "Done", confirmLabel = "Press again to confirm", holdMs = 1200, onCommit, className, style }: Props) {
  const fill = useRef<HTMLSpanElement>(null);
  const reduce = useReducedMotion();
  const [done, setDone] = useState(false);
  const [armed, setArmed] = useState(false);
  // engaged: a pointer or key hold began for this activation, so the click that follows it is not an assistive-tech click
  const st = useRef({ p: 0, raf: 0, holding: false, last: 0, engaged: false, downAt: 0, armedAt: 0, timer: 0 });
  const loop = (t: number) => {
    const s = st.current; const dt = s.last ? t - s.last : 16; s.last = t;
    s.p = Math.max(0, Math.min(1, s.p + (s.holding ? dt / holdMs : -dt / (reduce ? holdMs : 300))));
    if (fill.current) fill.current.style.transform = `scaleX(${s.p})`;
    if (s.p >= 1 && s.holding) { s.holding = false; setDone(true); onCommit(); s.raf = 0; return; }
    s.raf = s.p > 0 || s.holding ? requestAnimationFrame(loop) : 0;
  };
  const start = () => { if (done) return; const s = st.current; s.engaged = true; s.downAt = performance.now(); s.holding = true; s.last = 0; if (!s.raf) s.raf = requestAnimationFrame(loop); };
  const stop = () => { const s = st.current; s.holding = false; s.last = 0; if (!s.raf && s.p > 0) s.raf = requestAnimationFrame(loop); };
  const disarm = () => { const s = st.current; clearTimeout(s.timer); s.armedAt = 0; setArmed(false); };
  // Assistive tech activates with a bare click (no pointerdown/keydown hold first). First click arms, second commits.
  const click = (e: { detail: number }) => {
    const s = st.current; if (done) return;
    const now = performance.now();
    // the click that ends a real hold is not an activation; a tap shorter than TAP_MS (VoiceOver's double-tap, a quick click) is
    if (s.engaged) { s.engaged = false; if (now - s.downAt >= TAP_MS) return; }
    if (e.detail > 1) return; // the second half of a double-click is never a confirmation
    if (s.armedAt && now - s.armedAt >= GAP_MS) { disarm(); s.p = 1; if (fill.current) fill.current.style.transform = "scaleX(1)"; setDone(true); onCommit(); return; }
    if (!s.armedAt) { s.armedAt = now; setArmed(true); clearTimeout(s.timer); s.timer = window.setTimeout(disarm, ARM_MS); }
  };
  const stopRef = useRef(stop); stopRef.current = stop; // the listeners below always call the latest stop()
  useEffect(() => {
    const s = st.current;
    const away = () => { if (s.holding) stopRef.current(); };
    const hidden = () => { if (document.hidden) away(); };
    window.addEventListener("blur", away); document.addEventListener("visibilitychange", hidden);
    return () => { cancelAnimationFrame(s.raf); s.raf = 0; s.holding = false; clearTimeout(s.timer);
      window.removeEventListener("blur", away); document.removeEventListener("visibilitychange", hidden); };
  }, []);
  return (
    <button type="button" className={className} disabled={done}
      onClick={click} onPointerDown={start} onPointerUp={stop} onPointerLeave={() => { stop(); st.current.engaged = false; }} onPointerCancel={() => { stop(); st.current.engaged = false; }} onContextMenu={(e) => e.preventDefault()}
      onKeyDown={(e) => { if ((e.key === " " || e.key === "Enter") && !e.repeat) { e.preventDefault(); start(); } }} onKeyUp={(e) => { if (e.key === " " || e.key === "Enter") { e.preventDefault(); stop(); st.current.engaged = false; } }}
      style={{ position: "relative", overflow: "hidden", font: "inherit", padding: "14px 26px", borderRadius: 999, border: "1px solid var(--ink, #111)", background: "var(--ground, #fff)", color: "var(--ink, #111)", cursor: "pointer", userSelect: "none", WebkitTouchCallout: "none", ...style }}>
      <span ref={fill} aria-hidden="true" style={{ position: "absolute", inset: 0, background: "var(--accent, #e0442b)", transformOrigin: "0 50%", transform: "scaleX(0)" }} />
      <span style={{ position: "relative" }}>{done ? doneLabel : armed ? confirmLabel : label}</span>
      <span aria-live="polite" style={{ position: "absolute", width: 1, height: 1, overflow: "hidden", clip: "rect(0 0 0 0)" }}>{done ? doneLabel : armed ? confirmLabel : ""}</span>
    </button>
  );
}

"use client";
// Motomation component helpers: the shared motion rules every component in examples/components follows.
// No dependencies beyond React. Each hook cleans up after itself and respects reduced motion.
import { useEffect, useRef, useState, useSyncExternalStore, type RefObject } from "react";

export const clamp = (v: number, lo = 0, hi = 1) => Math.min(hi, Math.max(lo, v));
export const lerp = (a: number, b: number, t: number) => a + (b - a) * t;

const query = (q: string) => (typeof window !== "undefined" && "matchMedia" in window ? window.matchMedia(q) : null);

/** Live media-query state, correct on the first client render: it reads the query while rendering (through
 *  useSyncExternalStore), so a reduced-motion user never gets one animated render before an effect corrects it.
 *  On the server there is no media query: it returns false there, and React re-renders with the real value on hydration. */
export function useMedia(q: string): boolean {
  return useSyncExternalStore(
    (onChange) => { const m = query(q); if (!m) return () => {}; m.addEventListener("change", onChange); return () => m.removeEventListener("change", onChange); },
    () => query(q)?.matches ?? false,
    () => false,
  );
}
/** True when the user asked for reduced motion. Components show their final state instead of animating. */
export const useReducedMotion = () => useMedia("(prefers-reduced-motion: reduce)");
/** True for a mouse or trackpad. Hover and cursor effects run only then. */
export const useFinePointer = () => useMedia("(hover: hover) and (pointer: fine)");
/** Motion is allowed: no reduced-motion preference. */
export const useMotionOK = () => !useReducedMotion();

/** Visibility of an element. With once, it stays true after the first time it enters. */
export function useInView<T extends Element>(ref: RefObject<T | null>, { once = true, margin = "0px 0px -10% 0px", threshold = 0 } = {}): boolean {
  const [seen, setSeen] = useState(false);
  useEffect(() => {
    const el = ref.current; if (!el || typeof IntersectionObserver === "undefined") { setSeen(true); return; }
    const io = new IntersectionObserver(([e]) => { if (e.isIntersecting) { setSeen(true); if (once) io.disconnect(); } else if (!once) setSeen(false); }, { rootMargin: margin, threshold });
    io.observe(el);
    return () => io.disconnect();
  }, [ref, once, margin, threshold]);
  return seen;
}

/**
 * Calls onProgress(0..1) as an element travels through the viewport (0 = its top meets the viewport bottom,
 * 1 = its bottom meets the viewport top). One rAF per frame at most, no React re-renders.
 * Pass enabled=false (for example under reduced motion) to stop listening.
 */
export function useScrollProgress<T extends HTMLElement>(ref: RefObject<T | null>, onProgress: (p: number) => void, enabled = true) {
  const cb = useRef(onProgress); cb.current = onProgress;
  useEffect(() => {
    if (!enabled) return;
    let raf = 0;
    const tick = () => {
      raf = 0; const el = ref.current; if (!el) return;
      const r = el.getBoundingClientRect(); const vh = window.innerHeight;
      cb.current(clamp((vh - r.top) / (r.height + vh)));
    };
    const ask = () => { if (!raf) raf = requestAnimationFrame(tick); };
    tick();
    window.addEventListener("scroll", ask, { passive: true }); window.addEventListener("resize", ask);
    return () => { window.removeEventListener("scroll", ask); window.removeEventListener("resize", ask); cancelAnimationFrame(raf); };
  }, [ref, enabled]);
}

/** Like useScrollProgress for a tall sticky wrapper: 0 when its top reaches the viewport top, 1 when its bottom reaches the viewport bottom. */
export function useStickyProgress<T extends HTMLElement>(ref: RefObject<T | null>, onProgress: (p: number) => void, enabled = true) {
  const cb = useRef(onProgress); cb.current = onProgress;
  useEffect(() => {
    if (!enabled) return;
    let raf = 0;
    const tick = () => { raf = 0; const el = ref.current; if (!el) return; const r = el.getBoundingClientRect(); const run = r.height - window.innerHeight; cb.current(run > 0 ? clamp(-r.top / run) : 0); };
    const ask = () => { if (!raf) raf = requestAnimationFrame(tick); };
    tick();
    window.addEventListener("scroll", ask, { passive: true }); window.addEventListener("resize", ask);
    return () => { window.removeEventListener("scroll", ask); window.removeEventListener("resize", ask); cancelAnimationFrame(raf); };
  }, [ref, enabled]);
}

/** Smoothed scroll velocity in px per frame, delivered every frame while it settles back to 0. */
export function useScrollVelocity(onVelocity: (v: number) => void, enabled = true) {
  const cb = useRef(onVelocity); cb.current = onVelocity;
  useEffect(() => {
    if (!enabled) return;
    let last = window.scrollY, v = 0, raf = 0;
    const loop = () => {
      const y = window.scrollY; v = lerp(v, y - last, 0.2); last = y; cb.current(v);
      raf = Math.abs(v) > 0.05 ? requestAnimationFrame(loop) : 0; if (!raf) cb.current(0);
    };
    const kick = () => { if (!raf) raf = requestAnimationFrame(loop); };
    window.addEventListener("scroll", kick, { passive: true });
    return () => { window.removeEventListener("scroll", kick); cancelAnimationFrame(raf); };
  }, [enabled]);
}

/** A frame loop that pauses when the element is off screen or the tab is hidden. */
export function useFrameLoop<T extends Element>(ref: RefObject<T | null>, frame: (t: number, dt: number) => void, enabled = true) {
  const cb = useRef(frame); cb.current = frame;
  useEffect(() => {
    if (!enabled) return;
    let raf = 0, visible = true, prev = 0;
    const run = (t: number) => { const dt = prev ? Math.min(64, t - prev) : 16; prev = t; cb.current(t, dt); raf = requestAnimationFrame(run); };
    const start = () => { if (!raf && visible && !document.hidden) { prev = 0; raf = requestAnimationFrame(run); } };
    const stop = () => { cancelAnimationFrame(raf); raf = 0; };
    const el = ref.current;
    const io = el && typeof IntersectionObserver !== "undefined" ? new IntersectionObserver(([e]) => { visible = e.isIntersecting; if (visible) start(); else stop(); }) : null;
    if (el && io) io.observe(el);
    const vis = () => (document.hidden ? stop() : start());
    document.addEventListener("visibilitychange", vis); start();
    return () => { stop(); io?.disconnect(); document.removeEventListener("visibilitychange", vis); };
  }, [ref, enabled]);
}

/** Shared timing tokens (motion/tokens.md). UI feedback stays at or under 250ms. */
export const EASE = { out: "cubic-bezier(0.22, 1, 0.36, 1)", outStrong: "cubic-bezier(0.16, 1, 0.3, 1)", inOut: "cubic-bezier(0.65, 0, 0.35, 1)", drawer: "cubic-bezier(0.32, 0.72, 0, 1)" } as const;
export const DUR = { press: 120, ui: 180, reveal: 800, stagger: 80 } as const;
